        const html2 = `<div class="script_actionTime" style="color: ${runtime.config.SCRIPT_COLOR_MAIN};">${isInfinit ? "[ ∞ ] " : `[${runtime.api.timeReadable(totalTimeSec)}]`} ${str}</div>`;
